const raw = $input.first().json;
const body = raw.body || raw;

// Generate unique applicant ID
const applicantId = `app-${Date.now()}`;

// Handle WhatsApp trigger format if needed
// WhatsApp sends messages in raw.entry[0].changes[0].value.messages[0]
const isWhatsApp = !!(raw.entry && raw.entry[0]?.changes);
let whatsAppMessage = null;
let whatsAppPhone = null;

if (isWhatsApp) {
  const msg = raw.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  whatsAppPhone = msg?.from || null;
  whatsAppMessage = msg?.text?.body || null;
}

return [{
  json: {
    // Core applicant fields
    applicantId,
    propertyId:       body.propertyId      || body.property_id   || null,
    applicantName:    body.applicantName    || body.name          || null,
    applicantEmail:   body.applicantEmail   || body.email         || null,
    applicantPhone:   body.applicantPhone   || body.phone
                      || whatsAppPhone      || null,
    monthlyIncome:    parseFloat(body.monthlyIncome || body.income || 0) || null,
    moveInDate:       body.moveInDate       || body.move_in       || null,
    pets:             body.pets                                   || null,
    occupants:        parseInt(body.occupants || '1')             || null,
    message:          body.message          || body.text
                      || whatsAppMessage    || null,

    // Workflow config
    CALENDLY_USERNAME:  'YOUR_CALENDLY_USERNAME',
    CALENDLY_EVENT_SLUG: 'property-viewing',
    MANAGER_EMAIL:      'user@example.com',
    MANAGER_NAME:       'Your Name',

    // Metadata
    timestamp:    new Date().toISOString(),
    source:       isWhatsApp ? 'WhatsApp' : 'Webhook'
  }
}];

const applicant = $('Normalize Applicant Details').first().json;

// Airtable returns records array — extract first match
const raw = $input.first().json;
const property = raw.fields || raw;

// Calculate income ratio for prompt context
const rent = parseFloat(property['Monthly Rent'] || 0);
const minIncome = parseFloat(property['Min Income Required'] || rent * 3);
const incomeRatio = rent > 0 ? (minIncome / rent).toFixed(1) : '3.0';

return [{
  json: {
    // Applicant fields
    applicantId:    applicant.applicantId,
    applicantName:  applicant.applicantName,
    applicantEmail: applicant.applicantEmail,
    applicantPhone: applicant.applicantPhone,
    monthlyIncome:  applicant.monthlyIncome,
    moveInDate:     applicant.moveInDate,
    pets:           applicant.pets,
    occupants:      applicant.occupants,
    message:        applicant.message,
    timestamp:      applicant.timestamp,
    source:         applicant.source,

    // Property fields from Airtable
    propertyId:       property['Property ID']             || applicant.propertyId,
    propertyName:     property['Property Name']           || 'the property',
    address:          property['Address']                 || null,
    monthlyRent:      rent,
    minIncomeRequired: minIncome,
    incomeRatio,
    petPolicy:        property['Pet Policy']              || 'Not specified',
    maxOccupants:     property['Max Occupants']           || null,
    availableFrom:    property['Available From']          || null,
    propertyType:     property['Property Type']           || null,
    bedrooms:         property['Bedrooms']                || null,
    bathrooms:        property['Bathrooms']               || null,
    applicationUrl:   property['Application URL']         || null,
    applicationFee:   property['Application Fee']         || null,
    managerEmail:     property['Property Manager Email']  || applicant.MANAGER_EMAIL,
    description:      property['Description']             || null,

    // Config
    CALENDLY_USERNAME:  applicant.CALENDLY_USERNAME,
    CALENDLY_EVENT_SLUG: applicant.CALENDLY_EVENT_SLUG,
    MANAGER_EMAIL:      applicant.MANAGER_EMAIL,
    MANAGER_NAME:       applicant.MANAGER_NAME
  }
}];

