// ============================================================
const PREPARE_NODE = 'Prepare Gemini Input';
// ============================================================

const prepData = $(PREPARE_NODE).first().json;
const allItems = $input.all();

// Extract Gemini output
let rawText = '';
for (const item of allItems) {
  const text = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output || '';
  if (text && text.includes('qualificationScore')) {
    rawText = text;
    break;
  }
}

const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

// Parse with fallback
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    extractedIncome:    null,
    extractedMoveIn:    null,
    extractedPets:      null,
    extractedOccupants: null,
    qualificationScore: 'Borderline',
    scoreReasoning:     'AI parsing failed — manual review recommended.',
    missingInfo:        'Unable to automatically qualify — please review manually.',
    email_subject:      `Re: Your Inquiry for ${prepData.propertyName}`,
    email_body:         `Dear ${prepData.applicantName},\n\nThank you for your interest in ${prepData.propertyName}. We would like to learn a little more about your situation before proceeding. Could you please provide your monthly income, preferred move-in date, and any pets you may have?`
  };
}

// HTML formatter
function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatEmailHtml(text) {
  if (!text) return '';
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  return paragraphs.map(p => `<p>${escapeHtml(p)}</p>`).join('');
}

// Build Calendly booking link
const calendlyUsername = prepData.CALENDLY_USERNAME || '';
const calendlySlug = prepData.CALENDLY_EVENT_SLUG || 'property-viewing';
const bookingLink = calendlyUsername && calendlyUsername !== 'YOUR_CALENDLY_USERNAME'
  ? `https://calendly.com/${calendlyUsername}/${calendlySlug}`
  : null;

// Build application CTA for Qualified response
const applicationHtml = prepData.applicationUrl
  ? `<p>
       <a href="${escapeHtml(prepData.applicationUrl)}" 
          style="background:#27ae60;color:white;padding:12px 24px;
          border-radius:6px;text-decoration:none;font-weight:bold;">
         Complete Your Application →
       </a>
     </p>
     ${prepData.applicationFee
       ? `<p style="color:#666;font-size:14px;">Application fee: ${escapeHtml(prepData.applicationFee)}</p>`
       : ''}
     ${bookingLink
       ? `<p><a href="${escapeHtml(bookingLink)}" style="color:#3498db;">📅 Schedule a viewing</a></p>`
       : ''}`
  : '';

return [{
  json: {
    // All prepared data fields carried forward
    ...prepData,

    // AI extracted fields
    extractedIncome:    parsed.extractedIncome,
    extractedMoveIn:    parsed.extractedMoveIn,
    extractedPets:      parsed.extractedPets,
    extractedOccupants: parsed.extractedOccupants,

    // Qualification
    qualificationScore: parsed.qualificationScore,
    scoreReasoning:     parsed.scoreReasoning,
    missingInfo:        parsed.missingInfo,

    // Email content
    email_subject:   parsed.email_subject,
    email_body:      formatEmailHtml(parsed.email_body),
    applicationHtml,
    bookingLink,

    // Metadata
    applicantId: prepData.applicantId,
    timestamp:   prepData.timestamp
  }
}];

const allApplicants = $input.all().map(i => i.json.fields || i.json);
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

function escapeHtml(text) {
  if (!text) return 'N/A';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Count by score
const qualified   = allApplicants.filter(a => a['Qualification Score'] === 'Qualified');
const borderline  = allApplicants.filter(a => a['Qualification Score'] === 'Borderline');
const unqualified = allApplicants.filter(a => a['Qualification Score'] === 'Unqualified');

// Group by property
const byProperty = {};
for (const applicant of allApplicants) {
  const prop = applicant['Property Name'] || 'Unknown Property';
  if (!byProperty[prop]) byProperty[prop] = [];
  byProperty[prop].push(applicant);
}

// Build property sections
let propertySections = '';
for (const [propName, applicants] of Object.entries(byProperty)) {
  const propAddress = applicants[0]?.['Address'] || '';
  const propRent = applicants[0]?.['Monthly Rent'] || '';

  let rows = '';
  for (const a of applicants) {
    const score = a['Qualification Score'] || 'Unknown';
    const emoji = score === 'Qualified' ? '✅'
      : score === 'Borderline' ? '⚠️' : '❌';
    const color = score === 'Qualified' ? '#27ae60'
      : score === 'Borderline' ? '#f39c12' : '#e74c3c';

    rows += `
      <tr style="border-bottom:1px solid #eee;">
        <td style="padding:10px 8px;">
          ${emoji} <strong>${escapeHtml(a['Applicant Name'])}</strong>
        </td>
        <td style="padding:10px 8px;color:${color};font-weight:bold;">
          ${escapeHtml(score)}
        </td>
        <td style="padding:10px 8px;color:#555;font-size:13px;">
          Income: ${a['Monthly Income'] ? '$' + Number(a['Monthly Income']).toLocaleString() : 'Not stated'} |
          Move-in: ${escapeHtml(a['Move-in Date'])} |
          Pets: ${escapeHtml(a['Pets'])}
        </td>
        <td style="padding:10px 8px;color:#666;font-size:12px;max-width:250px;">
          ${escapeHtml(a['Score Reasoning'])}
        </td>
      </tr>`;
  }

  propertySections += `
    <div style="margin:24px 0;">
      <h3 style="color:#1a1a2e;margin:0 0 4px 0;">
        🏠 ${escapeHtml(propName)}
      </h3>
      <p style="color:#888;font-size:13px;margin:0 0 12px 0;">
        ${escapeHtml(propAddress)} | 
        ${propRent ? '$' + Number(propRent).toLocaleString() + '/mo' : ''}
      </p>
      <table style="width:100%;border-collapse:collapse;font-size:14px;">
        <thead>
          <tr style="background:#f8f9fa;">
            <th style="padding:8px;text-align:left;">Applicant</th>
            <th style="padding:8px;text-align:left;">Score</th>
            <th style="padding:8px;text-align:left;">Details</th>
            <th style="padding:8px;text-align:left;">Reasoning</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

// Full digest HTML
const digestHtml = `
  <div style="font-family:Arial,sans-serif;max-width:780px;margin:0 auto;color:#333;">
    <div style="background:#1a1a2e;color:white;padding:24px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;">🏘 Rental Applicant Daily Digest</h2>
      <p style="margin:8px 0 0 0;opacity:0.8;">${today}</p>
    </div>
    <div style="background:#f8f9fa;padding:14px 24px;border-bottom:1px solid #ddd;">
      <p style="margin:0;font-size:14px;">
        Total inquiries: <strong>${allApplicants.length}</strong> &nbsp;|&nbsp;
        ✅ Qualified: <strong>${qualified.length}</strong> &nbsp;|&nbsp;
        ⚠️ Borderline: <strong>${borderline.length}</strong> &nbsp;|&nbsp;
        ❌ Unqualified: <strong>${unqualified.length}</strong>
      </p>
    </div>
    <div style="padding:24px;background:white;">
      ${propertySections}
    </div>
    <div style="background:#f8f9fa;padding:16px 24px;border-top:1px solid #ddd;
      border-radius:0 0 8px 8px;font-size:12px;color:#888;">
      Powered by QualMatic AI | All applicants responded to automatically.
    </div>
  </div>
`;

return [{
  json: {
    digestHtml,
    digestSubject: `🏘 ${allApplicants.length} rental applicant${allApplicants.length > 1 ? 's' : ''} today — ${qualified.length} qualified`,
    totalApplicants:  allApplicants.length,
    qualifiedCount:   qualified.length,
    borderlineCount:  borderline.length,
    unqualifiedCount: unqualified.length,
    digestDate:       new Date().toISOString().substring(0, 10)
  }
}];

const propertyId = $('Normalize Applicant Details').first().json.propertyId;
const allRows = $input.all().map(i => i.json);

const match = allRows.find(row =>
  String(row['Property ID'] || '').trim().toLowerCase() ===
  String(propertyId || '').trim().toLowerCase()
);

if (!match) {
  return [{ json: { propertyFound: false, propertyId } }];
}

return [{ json: { ...match, propertyFound: true } }];

const today = new Date().toISOString().substring(0, 10);
const allRows = $input.all().map(i => i.json);

const todayRows = allRows.filter(row => {
  const ts = String(row['Timestamp'] || '');
  return ts.startsWith(today);
});

return todayRows.map(row => ({ json: row }));
